package pe.edu.utec.labreserve.config;
import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Profile; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import pe.edu.utec.labreserve.entity.*; import pe.edu.utec.labreserve.repository.*; import java.math.BigDecimal;
@Component @Profile("!test") public class DataInitializer implements CommandLineRunner{private final UserRepository users; private final StoreRepository stores; private final ProductRepository products; private final PasswordEncoder enc; public DataInitializer(UserRepository users,StoreRepository stores,ProductRepository products,PasswordEncoder enc){this.users=users;this.stores=stores;this.products=products;this.enc=enc;} public void run(String...a){if(users.count()>0)return; User admin=users.save(new User("admin","admin@utec.edu.pe",enc.encode("AdminPass2026"),RoleConstants.ROLE_ADMIN)); User vendor=users.save(new User("vendor","vendor@utec.edu.pe",enc.encode("VendorPass2026"),RoleConstants.ROLE_VENDOR)); users.save(new User("maria.eats","maria@utec.edu.pe",enc.encode("Campus2026"),RoleConstants.ROLE_CUSTOMER)); Store s=stores.save(new Store("Piso 2 Café",vendor.getId(),"Piso 2","OPEN")); products.save(new Product(s.getId(),"Bowl de quinua",new BigDecimal("18.50"),25,"AVAILABLE"));}}
